.sect-head{margin-bottom:56px}
.sect-title{font-family:'Fraunces',Georgia,serif;font-size:clamp(26px,3.8vw,44px);font-weight:600;letter-spacing:-0.03em;color:#f9fafb;margin:10px 0;line-height:1.1}
.sect-sub{color:var(--muted);font-size:15px;line-height:1.65;margin-top:10px;max-width:52ch}
.steps-grid{display:grid;grid-template-columns:1fr;gap:18px}
@media(min-width:768px){.steps-grid{grid-template-columns:repeat(3,1fr)}}
.step{
  background:linear-gradient(180deg,#161310 0%,#0f0d0b 100%);
  border:1px solid var(--border);border-radius:20px;padding:32px;
  position:relative;overflow:hidden;transition:all .35s ease;
}
.step::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(251,191,36,0.28),transparent)}
.step:hover{border-color:rgba(251,191,36,0.22);transform:translateY(-4px);box-shadow:0 20px 55px rgba(0,0,0,0.48)}
.step-n{font-family:'Fraunces',Georgia,serif;font-size:46px;font-weight:700;color:rgba(251,191,36,0.13);line-height:1;margin-bottom:18px;letter-spacing:-0.05em}
.step-ico{width:42px;height:42px;background:rgba(251,191,36,0.09);border:1px solid rgba(251,191,36,0.18);border-radius:11px;display:flex;align-items:center;justify-content:center;color:var(--amber);margin-bottom:18px}
.step-t{font-family:'Fraunces',Georgia,serif;font-size:21px;font-weight:600;color:#f9fafb;margin-bottom:10px}
.step-b{font-size:13.5px;color:var(--muted);line-height:1.65}
.match-ex{margin-top:18px;background:rgba(245,241,234,0.03);border:1px solid var(--border);border-radius:11px;padding:13px}
.me-h{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}
.me-nm{font-size:13px;font-weight:600;color:var(--text)}
.me-pct{font-family:'Fraunces',serif;font-size:15px;font-weight:600;color:var(--amber)}
.bar-t{height:4px;border-radius:999px;background:rgba(245,241,234,0.06);overflow:hidden}
.bar-f{height:100%;background:linear-gradient(90deg,var(--deep),var(--amber));border-radius:999px}

/* TRUST */
.trust-wrap{
  padding:96px 24px;
  background:linear-gradient(180deg,transparent,rgba(18,16,14,0.4));
  border-top:1px solid var(--border);
}
.trust-inner{max-width:1280px;margin:0 auto}
.trust-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:48px}
@media(min-width:768px){.trust-grid{grid-template-columns:repeat(4,1fr)}}
.trust-stat{
  padding:26px;background:linear-gradient(180deg,#161310 0%,#0f0d0b 100%);
  border:1px solid var(--border);border-radius:18px;position:relative;text-align:center;
}
.trust-stat::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;border-radius:18px 18px 0 0;background:linear-gradient(90deg,transparent,rgba(251,191,36,0.22),transparent)}
.trust-n{font-family:'Fraunces',Georgia,serif;font-size:34px;font-weight:700;color:var(--amber);letter-spacing:-0.02em;margin-bottom:5px}
.trust-l{font-size:12px;color:var(--muted);line-height:1.45}

/* Testimonial */
.testimonial{
  margin:48px auto 0;max-width:740px;
  padding:30px;background:linear-gradient(180deg,#161310,#0f0d0b);
  border:1px solid var(--border);border-radius:20px;position:relative;overflow:hidden;
}
.testimonial::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(251,191,36,0.28),transparent)}
.testimonial p{font-family:'Fraunces',Georgia,serif;font-size:18px;line-height:1.55;color:var(--text2);font-style:italic;margin:16px 0}
.test-author{display:flex;align-items:center;gap:12px}
.test-av{width:34px;height:34px;border-radius:50%;background:linear-gradient(135deg,rgba(251,191,36,0.28),rgba(217,119,6,0.12));border:1px solid rgba(251,191,36,0.28);display:flex;align-items:center;justify-content:center;color:var(--amber);font-size:13px;font-weight:600;flex-shrink:0}
.test-nm{font-size:13.5px;font-weight:600;color:var(--text)}
.test-loc{font-size:12px;color:var(--muted)}

/* CTA */
.cta-section{padding:96px 24px;text-align:center;position:relative;overflow:hidden}
.cta-glow{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:600px;height:380px;background:radial-gradient(ellipse,rgba(251,191,36,0.09) 0%,transparent 70%);pointer-events:none}
.cta-in{position:relative;z-index:2;max-width:580px;margin:0 auto}
.cta-title{font-family:'Fraunces',Georgia,serif;font-size:clamp(30px,4.5vw,50px);font-weight:600;letter-spacing:-0.035em;color:#f9fafb;margin:14px 0}
.cta-sub{color:var(--muted);font-size:15.5px;line-height:1.65;margin-bottom:32px;max-width:44ch;margin-left:auto;margin-right:auto}
.cta-form{display:flex;gap:9px;max-width:420px;margin:0 auto;flex-wrap:wrap;justify-content:center}
.cta-inp{
  flex:1;min-width:200px;background:rgba(245,241,234,0.04);border:1px solid var(--border);
  border-radius:999px;padding:12px 20px;font-size:14px;color:var(--text);
  font-family:inherit;outline:none;transition:border-color .2s;
}
.cta-inp::placeholder{color:var(--muted2)}
.cta-inp:focus{border-color:rgba(251,191,36,0.38)}
.cta-note{font-size:11.5px;color:var(--muted2);margin-top:13px}

/* FOOTER */
.footer{border-top:1px solid var(--border);padding:48px 24px 32px;background:var(--bg)}
.footer-in{max-width:1280px;margin:0 auto}
.footer-top{display:grid;grid-template-columns:1fr;gap:32px;margin-bottom:40px}
@media(min-width:768px){.footer-top{grid-template-columns:1.5fr 1fr 1fr 1fr}}
.footer-brand p{font-size:13.5px;color:var(--muted);line-height:1.65;margin-top:12px;max-width:34ch}
.footer-col h4{font-size:10.5px;letter-spacing:0.18em;text-transform:uppercase;color:var(--muted2);margin-bottom:14px}
.footer-col ul{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:9px}
.footer-col li a{font-size:13.5px;color:var(--muted);transition:color .2s}
.footer-col li a:hover{color:var(--text)}
.footer-bot{border-top:1px solid var(--border);padding-top:22px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px}
.footer-bot p{font-size:11.5px;color:var(--muted2)}

/* REVEAL */
[data-r]{opacity:0;transform:translateY(18px);transition:opacity .65s cubic-bezier(.2,.8,.2,1),transform .65s cubic-bezier(.2,.8,.2,1)}
[data-r].vis{opacity:1;transform:none}

/* SCROLLBAR */
::-webkit-scrollbar{width:9px}
::-webkit-scrollbar-track{background:var(--bg)}
::-webkit-scrollbar-thumb{background:var(--border);border-radius:9px}
::-webkit-scrollbar-thumb:hover{background:var(--bronze)}
:focus-visible{outline:2px solid var(--amber);outline-offset:2px;border-radius:5px}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important}}

/* ── HERO VIDEO BACKGROUND ─────────────────────────────────────────────────── */
.hero-vid-wrap{position:absolute;inset:0;z-index:0;overflow:hidden;pointer-events:none}
.hero-vid-wrap video{width:100%;height:100%;object-fit:cover;opacity:0.44;transition:opacity .8s ease}
.hero-vid-overlay{
  position:absolute;inset:0;
  background:
    linear-gradient(180deg,rgba(10,9,8,0.62) 0%,rgba(10,9,8,0.18) 42%,rgba(10,9,8,0.68) 100%),
    radial-gradient(ellipse 70% 80% at 55% 50%,rgba(10,9,8,0.08) 0%,rgba(10,9,8,0.52) 70%);
}


.bento-body {
  position: relative;
  z-index: 2;
}
.bento-eyebrow {
  font-size: 10.5px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 10px;
}
.bento-title {
  font-family: Fraunces, Georgia, serif;
  font-size: clamp(18px, 2.2vw, 26px);
  font-weight: 600;
  color: #f9fafb;
  line-height: 1.15;
  margin-bottom: 10px;
}
.bento-stat {
  font-size: 12px;
  color: var(--amber);
  font-weight: 500;
}
.bento-cta {
  margin-top: 18px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: rgba(251,191,36,0.08);
  border: 1px solid var(--border-warm);
  border-radius: 999px;
  padding: 8px 16px;
  font-size: 12.5px;
  color: var(--amber);
  font-family: inherit;
  cursor: pointer;
  transition: all 0.2s ease;
  width: fit-content;
}
.bento-cta:hover {
  background: rgba(251,191,36,0.15);
}
@media (max-width: 768px) {
  .bento-grid {
    grid-template-columns: 1fr;
    grid-template-rows: auto;
  }
  .bento-nl, .bento-de, .bento-be { grid-column: 1; grid-row: auto; }
  .bento-card { min-height: 220px; }
  .bento-pl { display: flex; }
}

/* ── CUSTOM CURSOR ─────────────────────────────────────────────────────────── */
body{cursor:none}
a,button,input,textarea,select,[role=button]{cursor:none}
.cursor-dot{
  position:fixed;top:0;left:0;width:7px;height:7px;border-radius:50%;
  background:var(--amber);pointer-events:none;z-index:10000;
  transform:translate(-50%,-50%);
  box-shadow:0 0 10px rgba(251,191,36,0.8);
  transition:width .18s ease,height .18s ease,background .18s ease,box-shadow .18s ease;
  will-change:left,top;
}
.cursor-aura{
  position:fixed;top:0;left:0;width:52px;height:52px;border-radius:50%;
  pointer-events:none;z-index:9999;
  transform:translate(-50%,-50%);
  background:radial-gradient(circle,rgba(251,191,36,0.22) 0%,rgba(217,119,6,0.1) 38%,transparent 70%);
  filter:blur(11px);
  transition:width .38s cubic-bezier(.2,.8,.2,1),height .38s cubic-bezier(.2,.8,.2,1);
  will-change:left,top;
}
.cursor-dot.hov{width:12px;height:12px;background:#fde68a;box-shadow:0 0 18px rgba(251,191,36,1)}
.cursor-aura.hov{width:88px;height:88px}

/* ── IMPROVED HOVER STATES ─────────────────────────────────────────────────── */
.step{transition:border-color .38s cubic-bezier(.2,.8,.2,1),transform .38s cubic-bezier(.2,.8,.2,1),box-shadow .38s cubic-bezier(.2,.8,.2,1),background .38s cubic-bezier(.2,.8,.2,1)}
.step:hover{
  border-color:rgba(251,191,36,0.4)!important;
  transform:translateY(-7px) scale(1.016)!important;
  box-shadow:0 30px 70px rgba(0,0,0,0.58),0 0 0 1px rgba(251,191,36,0.11),inset 0 1px 0 rgba(251,191,36,0.14)!important;
  background:linear-gradient(180deg,#1d1812 0%,#110f0a 100%)!important;
}
.chip{transition:border-color .25s cubic-bezier(.2,.8,.2,1),background .25s,color .25s,transform .25s,box-shadow .25s}
.chip:hover{
  border-color:rgba(251,191,36,0.4);
  background:rgba(251,191,36,0.1);
  color:var(--text);
  transform:translateY(-2px);
  box-shadow:0 6px 18px rgba(251,191,36,0.16);
}
.mkt-stat{transition:border-color .34s cubic-bezier(.2,.8,.2,1),transform .34s cubic-bezier(.2,.8,.2,1),box-shadow .34s cubic-bezier(.2,.8,.2,1)}
.mkt-stat:hover{
  border-color:rgba(251,191,36,0.34)!important;
  transform:translateY(-5px)!important;
  box-shadow:0 16px 40px rgba(0,0,0,0.48),0 0 0 1px rgba(251,191,36,0.07)!important;
}

/* ── SHOP BY CATEGORY ──────────────────────────────────────────────────────── */
.cat-section{padding:72px 0;border-bottom:1px solid var(--border)}
.cat-head{max-width:1280px;margin:0 auto 28px;padding:0 24px}
@media(min-width:1024px){.cat-head{padding:0 52px}}
.cat-scroll{
  display:flex;gap:16px;overflow-x:auto;padding:4px 24px 16px;
  scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;
}
@media(min-width:1024px){.cat-scroll{padding:4px 52px 16px}}
.cat-scroll::-webkit-scrollbar{height:8px}
.cat-scroll::-webkit-scrollbar-track{background:var(--bg)}
.cat-scroll::-webkit-scrollbar-thumb{background:var(--border);border-radius:9px}
.cat-card{
  flex:0 0 200px;scroll-snap-align:start;
  background:linear-gradient(180deg,#161310 0%,#0f0d0b 100%);
  border:1px solid var(--border);border-radius:18px;padding:22px 20px;
  display:flex;flex-direction:column;align-items:flex-start;gap:14px;
  text-align:left;position:relative;overflow:hidden;
  transition:transform .35s cubic-bezier(.2,.8,.2,1),border-color .35s ease,box-shadow .35s ease;
}
.cat-card::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(251,191,36,0.28),transparent)}
.cat-card:hover,.cat-card:focus-visible{
  transform:translateY(-6px) scale(1.035);
  border-color:rgba(251,191,36,0.42);
  box-shadow:0 22px 55px rgba(0,0,0,0.5),0 0 0 1px rgba(251,191,36,0.12);
}
.cat-card.active{
  border-color:rgba(251,191,36,0.55);
  box-shadow:0 22px 55px rgba(0,0,0,0.5),0 0 0 1px rgba(251,191,36,0.2);
}
.cat-icon{position:relative;width:100%;height:56px;display:flex;align-items:center;justify-content:flex-start;color:var(--amber);opacity:.95}
.cat-badge{position:absolute;top:-2px;right:18%;color:var(--bronze)}
.cat-name{font-family:'Fraunces',Georgia,serif;font-size:19px;font-weight:600;color:#f9fafb}
.cat-sub{font-size:12px;color:var(--muted);margin-top:-8px}

/* ── PRICE INTELLIGENCE BANNER ─────────────────────────────────────────────── */
.price-banner{
  border-top:1px solid var(--border);border-bottom:1px solid var(--border);
  background:linear-gradient(90deg,rgba(52,211,153,0.05),rgba(251,191,36,0.05));
  padding:16px 24px;
}
.price-banner-in{
  max-width:1280px;margin:0 auto;display:flex;align-items:center;justify-content:center;
  gap:16px;flex-wrap:wrap;text-align:center;
}
.price-banner-text{font-size:13.5px;color:var(--text2)}
.price-banner-text strong{color:var(--amber);font-family:'Fraunces',Georgia,serif;font-weight:600}

/* ── READY TODAY ───────────────────────────────────────────────────────────── */
.ready-section{padding:72px 0;border-bottom:1px solid var(--border)}
.ready-head{max-width:1280px;margin:0 auto 28px;padding:0 24px}
@media(min-width:1024px){.ready-head{padding:0 52px}}
.ready-scroll{
  display:flex;gap:16px;overflow-x:auto;padding:4px 24px 16px;
  scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;
}
@media(min-width:1024px){.ready-scroll{padding:4px 52px 16px}}
.ready-scroll::-webkit-scrollbar{height:8px}
.ready-scroll::-webkit-scrollbar-track{background:var(--bg)}
.ready-scroll::-webkit-scrollbar-thumb{background:var(--border);border-radius:9px}
.ready-card{
  flex:0 0 270px;scroll-snap-align:start;
  background:linear-gradient(180deg,#161310 0%,#0f0d0b 100%);
  border:1px solid var(--border);border-radius:18px;overflow:hidden;
  display:flex;flex-direction:column;
  transition:border-color .3s ease,transform .3s ease,box-shadow .3s ease;
}
.ready-card:hover{border-color:rgba(251,191,36,0.32);transform:translateY(-4px);box-shadow:0 18px 45px rgba(0,0,0,0.45)}
.ready-img{height:148px;position:relative;background-size:cover;background-position:center;background-color:#1c1916}
.ready-img::after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(10,9,8,0) 40%,rgba(10,9,8,0.85) 100%)}
.ready-loc-badge{
  position:absolute;top:10px;left:10px;z-index:1;
  background:rgba(10,9,8,0.78);backdrop-filter:blur(8px);
  border:1px solid var(--border);border-radius:999px;padding:4px 10px;
  font-size:11px;font-weight:600;color:var(--text2);display:inline-flex;align-items:center;gap:5px;
}
.ready-body{padding:16px;display:flex;flex-direction:column;gap:8px;flex:1}
.ready-title{font-family:'Fraunces',Georgia,serif;font-size:16px;font-weight:600;color:#f9fafb;line-height:1.3}
.ready-price{font-family:'Fraunces',Georgia,serif;font-size:20px;font-weight:700;color:var(--amber)}
.ready-meta{display:flex;flex-wrap:wrap;gap:6px}
.ready-tag{font-size:11px;font-weight:500;color:var(--text2);background:rgba(245,241,234,0.04);border:1px solid var(--border);border-radius:999px;padding:3px 10px;text-transform:capitalize}
.ready-cta{
  margin-top:auto;display:inline-flex;align-items:center;justify-content:center;gap:6px;
  border:1px solid var(--border-warm);border-radius:999px;padding:9px 14px;
  font-size:12.5px;font-weight:600;color:var(--amber);transition:all .25s ease;
}
.ready-cta:hover{background:rgba(251,191,36,0.08);border-color:rgba(251,191,36,0.5)}
.ready-view-all{
  flex:0 0 160px;scroll-snap-align:start;display:flex;align-items:center;justify-content:center;
  border:1px dashed var(--border);border-radius:18px;color:var(--muted);font-size:13px;font-weight:600;
  transition:all .25s ease;text-align:center;padding:20px;
}
.ready-view-all:hover{border-color:rgba(251,191,36,0.4);color:var(--amber);background:rgba(251,191,36,0.04)}

/* Skeleton loading cards */
.ready-skel{flex:0 0 270px;scroll-snap-align:start;border-radius:18px;overflow:hidden;background:linear-gradient(180deg,#161310,#0f0d0b);border:1px solid var(--border)}
.ready-skel .sk-img{height:148px;background:linear-gradient(110deg,#1c1916 8%,#221f1b 18%,#1c1916 33%);background-size:200% 100%;animation:skShimmer 1.6s linear infinite}
.ready-skel .sk-line{height:12px;margin:14px 16px 0;border-radius:6px;background:linear-gradient(110deg,#1c1916 8%,#221f1b 18%,#1c1916 33%);background-size:200% 100%;animation:skShimmer 1.6s linear infinite}
.ready-skel .sk-line:last-child{margin-bottom:14px}
.ready-skel .sk-line.w60{width:60%}
.ready-skel .sk-line.w40{width:40%}
@keyframes skShimmer{to{background-position-x:-200%}}
@media(prefers-reduced-motion:reduce){.ready-skel .sk-img,.ready-skel .sk-line{animation:none}}

/* ══════ HERO BENTO GRID ══════ */
.hero-bento{
  display:grid;
  grid-template-columns:1.45fr 1fr;
  grid-template-rows:auto auto;
  gap:12px;
  max-width:1180px;
  margin:0 auto;
  padding:80px 24px 64px;
  width:100%;
}
@media(max-width:900px){
  .hero-bento{grid-template-columns:1fr;padding:48px 16px 40px}
}

.hb-chat{
  grid-column:1;grid-row:1 / 3;
  background:linear-gradient(180deg,#161310 0%,#0f0d0b 100%);
  border:1px solid var(--border);border-radius:18px;overflow:hidden;
  box-shadow:0 28px 70px rgba(0,0,0,0.55),0 0 0 1px rgba(245,241,234,0.03);
  position:relative;display:flex;flex-direction:column;min-height:0;
}
.hb-chat-top-line{position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(251,191,36,0.35),transparent)}
.hb-chat .chat-msgs{flex:1 1 auto;overflow-y:auto;min-height:120px}
.hb-chat .chat-input-row{margin-top:auto}

/* user (sent) chat bubble */
.chat-bubble.user{background:rgba(251,191,36,0.10);border:1px solid var(--border-warm);color:var(--text)}
.av.user-av{background:linear-gradient(135deg,rgba(251,191,36,0.18),rgba(217,119,6,0.10))}

.hb-headline{
  grid-column:2;grid-row:1;
  background:linear-gradient(160deg,#1a1410 0%,#110e0b 100%);
  border:1px solid var(--border);border-radius:18px;
  padding:28px 28px 24px;display:flex;flex-direction:column;justify-content:space-between;gap:14px;
  position:relative;overflow:hidden;
}
.hb-headline::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(251,191,36,0.22),transparent)}

.hb-stats{
  grid-column:2;grid-row:2;
  background:linear-gradient(160deg,#141210 0%,#0f0d0b 100%);
  border:1px solid var(--border);border-radius:18px;
  padding:22px 24px;display:grid;grid-template-columns:1fr 1fr;gap:16px 12px;
  position:relative;overflow:hidden;
}
.hb-stats::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(251,191,36,0.18),transparent)}
.hb-stat-item{display:flex;flex-direction:column;gap:3px}
.hb-stat-n{font-family:'Fraunces',Georgia,serif;font-size:26px;font-weight:600;color:var(--amber);letter-spacing:-0.02em;line-height:1}
.hb-stat-l{font-size:11px;color:var(--muted);letter-spacing:0.04em;line-height:1.4}

.hb-strip{grid-column:1 / -1;display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
@media(max-width:600px){.hb-strip{grid-template-columns:1fr}}
.hb-strip-card{
  background:linear-gradient(160deg,#141210 0%,#0f0d0b 100%);
  border:1px solid var(--border);border-radius:18px;padding:20px 22px;
  display:flex;align-items:center;gap:14px;
