.shroom-copy{display:flex;flex-direction:column;gap:18px}
.shroom-copy p{font-size:14.5px;color:var(--muted);line-height:1.7;margin:0;max-width:460px}
.shroom-chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:4px}
