.shroom-feat{display:flex;gap:12px;align-items:flex-start}
.shroom-feat-ico{
  width:34px;height:34px;flex-shrink:0;border-radius:10px;display:flex;align-items:center;justify-content:center;
  background:rgba(251,191,36,0.09);border:1px solid rgba(251,191,36,0.18);color:var(--amber);
}
.shroom-feat-t{font-size:14px;font-weight:600;color:var(--text);margin-bottom:2px}
.shroom-feat-d{font-size:12.5px;color:var(--muted);line-height:1.55}

/* Stage */
.shroom-stage{
  position:relative;border-radius:24px;overflow:hidden;
  background:
    radial-gradient(90% 70% at 50% 100%, rgba(251,191,36,0.07) 0%, transparent 60%),
    linear-gradient(180deg,#110f0c 0%,#0c0a08 100%);
  border:1px solid var(--border);
  box-shadow:0 30px 80px rgba(0,0,0,0.55),inset 0 1px 0 rgba(245,241,234,0.04);
  min-height:340px;height:clamp(340px,46vw,560px);
  cursor:grab;
}
.shroom-stage:active{cursor:grabbing}
.shroom-stage canvas{display:block;width:100%;height:100%;outline:none}
.shroom-floor{
  position:absolute;left:50%;bottom:7%;width:72%;height:13%;transform:translateX(-50%);
  background:radial-gradient(50% 50% at 50% 50%, rgba(0,0,0,0.6) 0%, transparent 72%);
  pointer-events:none;z-index:1;
}
.shroom-stage-top{height:1px;position:absolute;top:0;left:0;right:0;z-index:3;background:linear-gradient(90deg,transparent,rgba(251,191,36,0.3),transparent)}

/* Loader */
.shroom-load{
  position:absolute;inset:0;z-index:4;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;
  background:linear-gradient(180deg,#110f0c,#0c0a08);transition:opacity .6s ease;
}
.shroom-load.done{opacity:0;pointer-events:none}
.shroom-load-ring{
  width:44px;height:44px;border-radius:50%;
  border:2px solid rgba(251,191,36,0.15);border-top-color:var(--amber);
  animation:shroomSpin 0.9s linear infinite;
}
@keyframes shroomSpin{to{transform:rotate(360deg)}}
.shroom-load-txt{font-family:'JetBrains Mono','Fira Code',monospace;font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted)}
.shroom-load-txt b{color:var(--amber);font-weight:600}

/* Drag hint */
.shroom-hint{
  position:absolute;bottom:16px;left:50%;transform:translateX(-50%);z-index:5;
  display:flex;align-items:center;gap:9px;
  background:rgba(10,9,8,0.6);border:1px solid var(--border);border-radius:999px;
  padding:7px 16px;font-size:11.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--text2);
  backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);
  pointer-events:none;transition:opacity .5s ease;
}
.shroom-hint.hide{opacity:0}
.shroom-hint svg{color:var(--amber)}

/* Model badge */
.shroom-badge{
  position:absolute;top:16px;left:16px;z-index:5;display:flex;flex-direction:column;gap:2px;
  background:rgba(10,9,8,0.55);border:1px solid var(--border);border-radius:14px;padding:10px 16px;
  backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);pointer-events:none;
}
.shroom-badge-t{font-family:'Fraunces',Georgia,serif;font-size:15px;font-weight:600;color:#f9fafb}
.shroom-badge-s{font-family:'JetBrains Mono','Fira Code',monospace;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--amber)}

@media (max-width:640px){
  .shroom-stage{height:320px;border-radius:18px}
  .shroom-badge{padding:8px 12px}
}
</style>

