<script>
// ── Reveal on scroll ──────────────────────────────────────────────────────────
const revObs = new IntersectionObserver(entries => {
  entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('vis'); revObs.unobserve(e.target); }});
}, { threshold: 0.12 });
document.querySelectorAll('[data-r]').forEach(el => revObs.observe(el));

// Trigger hero reveals on load
window.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('.hero [data-r]').forEach((el, i) => {
    setTimeout(() => el.classList.add('vis'), 180 + i * 130);
  });
});

// ── Hero model subtle auto-drift ─────────────────────────────────────────────
const hModel = document.getElementById('bmw-hero');
let hAz = 315, hDrift = true, hTimer = null, hRaf = null;

function heroDrift() {
  if (!hDrift || !hModel) return;
  hAz += 0.012;
  if (hAz > 380) hAz = 290;
  hModel.setAttribute('camera-orbit', `${hAz.toFixed(3)}deg 72deg 4.2m`);
  hRaf = requestAnimationFrame(heroDrift);
}

if (hModel) {
  hModel.addEventListener('camera-change', () => {
    hDrift = false;
    if (hRaf) { cancelAnimationFrame(hRaf); hRaf = null; }
    clearTimeout(hTimer);
    hTimer = setTimeout(() => { hDrift = true; heroDrift(); }, 3200);
  });
  hModel.addEventListener('load', () => setTimeout(heroDrift, 800));
}

// ── Chat prompt fill ──────────────────────────────────────────────────────────
function fillChat(btn) {
  const inp = document.getElementById('chat-inp');
  if (inp) { inp.value = btn.textContent.trim(); inp.focus(); }
}

// ── Open the AI advisor with a pre-filled prompt ──────────────────────────────
function openAdvisorWithPrompt(text) {
  const panel = document.querySelector('.chat-panel');
  const inp = document.getElementById('chat-inp');
  if (panel) {
    panel.scrollIntoView({ behavior: 'smooth', block: 'center' });
    panel.classList.remove('flash');
    // Force reflow so the animation can re-trigger on repeated clicks
    void panel.offsetWidth;
    panel.classList.add('flash');
    panel.addEventListener('animationend', () => panel.classList.remove('flash'), { once: true });
  }
  if (inp) {
    inp.value = text;
    setTimeout(() => inp.focus(), 350);
  }
}

// ── Shop by category card clicks ──────────────────────────────────────────────
function shopCategory(card) {
