}

// ── Marquee hover pause ───────────────────────────────────────────────────────
const mq = document.getElementById('mqTrack');
if (mq) {
  mq.addEventListener('mouseenter', () => mq.style.animationPlayState = 'paused');
  mq.addEventListener('mouseleave', () => mq.style.animationPlayState = 'running');
}

// (Section-indicator dot clicks removed with the indicator dots.)

// ── Custom cursor ─────────────────────────────────────────────────────────────
const curDot  = document.getElementById('c-dot');
const curAura = document.getElementById('c-aura');
if (curDot && curAura) {
  let mx = window.innerWidth / 2, my = window.innerHeight / 2;
  let ax = mx, ay = my;

  document.addEventListener('mousemove', e => {
    mx = e.clientX; my = e.clientY;
    curDot.style.left = mx + 'px';
    curDot.style.top  = my + 'px';
  }, { passive: true });

  (function tickAura() {
    ax += (mx - ax) * 0.085;
    ay += (my - ay) * 0.085;
    curAura.style.left = ax.toFixed(1) + 'px';
    curAura.style.top  = ay.toFixed(1) + 'px';
    requestAnimationFrame(tickAura);
  })();

  const hovSel = 'a,button,[role=button],.chip,.mkt-stat,.step,.chat-btn,.val-row,.city-card,.trust-stat,.ab-badge,.btn-p,.btn-g';
  document.querySelectorAll(hovSel).forEach(el => {
    el.addEventListener('mouseenter', () => { curDot.classList.add('hov'); curAura.classList.add('hov'); });
    el.addEventListener('mouseleave', () => { curDot.classList.remove('hov'); curAura.classList.remove('hov'); });
  });
}

// ── Hero video cycling ────────────────────────────────────────────────────────
const heroVidEl = document.getElementById('hero-vid');
const heroVidSrcs = Array.from({ length: 7 }, (_, i) => `./media/Hero/Hero-0${i + 1}.mp4`);
let hvCur = 0;

if (heroVidEl) {
  function playHeroVid(idx) {
    heroVidEl.src = heroVidSrcs[idx];
    heroVidEl.play().catch(() => {});
  }
  heroVidEl.addEventListener('ended', () => {
    hvCur = (hvCur + 1) % heroVidSrcs.length;
    playHeroVid(hvCur);
  });
  // Start with a random video for variety on refresh
  hvCur = Math.floor(Math.random() * heroVidSrcs.length);
  playHeroVid(hvCur);
}

