function advisorReply(text){
  const t=(text||'').toLowerCase();
  if(/electric|\bev\b|range|charg/.test(t)) return "Good — EVs make sense in NL, which has Europe's densest charging network. What's your typical weekly distance and can you charge at home? I'll filter for real-world range that fits.";
  if(/family|kids|child|space|boot|suv|seats/.test(t)) return "Family-first, then. I'll prioritise boot space, ISOFIX points and low running costs. What's your budget and how many seats do you need?";
  if(/performance|manual|weekend|b-road|sport|fast|gearbox/.test(t)) return "A driver's car. Germany's market is where these make sense — manual, or open to DSG? And is it a daily or a weekend toy?";
  if(/budget|under|cheap|value|saving|€|euro/.test(t)) return "Let's anchor on value. Poland and Belgium often beat NL by 15–20% on the same spec. What's your ceiling, and is importing to NL OK?";
  return "Got it. Tell me your budget, how you'll use the car, and which markets you're open to — I'll surface live listings ranked by fit, not by who paid to be seen.";
}
