// ══════ Cost Calculator ══════
function eur(n){ return '€ ' + Math.round(n).toLocaleString('en-US'); }
function runCalc(){
  const price=parseFloat(document.getElementById('calc-price').value);
  const market=document.getElementById('calc-market').value;
  const age=Math.max(0, parseFloat(document.getElementById('calc-age').value)||0);
  const fuel=document.getElementById('calc-fuel').value;
  const result=document.getElementById('calc-result');
  if(!(price>0)){ result.style.display='none'; return; }

  // Simplified BPM by fuel, depreciated by age (EV exempt)
  const bpmRate={petrol:0.12, diesel:0.16, hybrid:0.06, ev:0}[fuel];
  const depr=Math.max(0.15, 1 - age*0.12);
  const bpm = fuel==='ev' ? 0 : price*bpmRate*depr;
  // Transport: further markets cost more; NL is domestic
  const transport={nl:0, be:180, de:380, pl:540}[market];
  const rdw = market==='nl' ? 0 : 94;
  const insurance = Math.max(620, price*0.045);
  const roadTax = {petrol:680, diesel:900, hybrid:300, ev:120}[fuel];
  const total = price + bpm + transport + rdw + insurance + roadTax;

  document.getElementById('r-price').textContent=eur(price);
  document.getElementById('r-bpm').textContent=eur(bpm);
  document.getElementById('r-transport').textContent= transport? eur(transport) : '€ 0 (domestic)';
  document.getElementById('r-rdw').textContent= rdw? eur(rdw) : '€ 0 (domestic)';
  document.getElementById('r-ins').textContent=eur(insurance);
  document.getElementById('r-tax').textContent=eur(roadTax);
  document.getElementById('r-total').textContent=eur(total);
  result.style.display='block';
}

// ══════ VIN Checker (structural decode demo) ══════
function runVin(){
  const el=document.getElementById('vin-input');
  let vin=(el.value||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  el.value=vin;
  const result=document.getElementById('vin-result');
  if(vin.length!==17){ result.style.display='none'; return; }

  const wmi=vin.substring(0,3);
  const makes={WBA:'BMW',WBS:'BMW M',WBY:'BMW i',WDB:'Mercedes-Benz',WDD:'Mercedes-Benz',WAU:'Audi',WUA:'Audi Sport',WVW:'Volkswagen',WV1:'VW Commercial',WP0:'Porsche',WP1:'Porsche SUV',TMB:'Škoda',VSS:'SEAT',VF1:'Renault',VF3:'Peugeot',VF7:'Citroën',ZFA:'Fiat',YV1:'Volvo',SAL:'Land Rover',SAJ:'Jaguar',JTD:'Toyota',SB1:'Toyota EU',VNK:'Toyota EU',KNA:'Kia',KMH:'Hyundai'};
  const make=makes[wmi] || makes[vin.substring(0,2)+'*'] || 'Unknown / niche (WMI '+wmi+')';
  const regions={W:'Germany',T:'Europe (Cz/Hu)',V:'Europe (Fr/Es)',Z:'Italy',Y:'Sweden/Finland',S:'United Kingdom',J:'Japan',K:'Korea',1:'United States',2:'Canada',3:'Mexico',4:'United States',5:'United States'};
  const region=regions[vin[0]] || 'Unknown';
  const yearMap={A:2010,B:2011,C:2012,D:2013,E:2014,F:2015,G:2016,H:2017,J:2018,K:2019,L:2020,M:2021,N:2022,P:2023,R:2024,S:2025,T:2026,V:2027,W:2028,X:2029,Y:2030,'1':2001,'2':2002,'3':2003,'4':2004,'5':2005,'6':2006,'7':2007,'8':2008,'9':2009};
  const year=yearMap[vin[9]] || 'Indeterminate';

  // Check digit (pos 9) ISO 3779 validation
  const translit={A:1,B:2,C:3,D:4,E:5,F:6,G:7,H:8,J:1,K:2,L:3,M:4,N:5,P:7,R:9,S:2,T:3,U:4,V:5,W:6,X:7,Y:8,Z:9};
  const weights=[8,7,6,5,4,3,2,10,0,9,8,7,6,5,4,3,2];
  let sum=0, ok=true;
  for(let k=0;k<17;k++){ const c=vin[k]; const v = /[0-9]/.test(c)? +c : translit[c]; if(v===undefined){ok=false;break;} sum+=v*weights[k]; }
  let checkOk=false;
  if(ok){ const r=sum%11; const expect = r===10?'X':String(r); checkOk = (expect===vin[8]); }
  const checkText = ok ? (checkOk ? 'Valid ✓' : 'Mismatch ✗') : 'Unverifiable';

  document.getElementById('v-make').textContent=make;
  document.getElementById('v-plant').textContent=vin[10];
  document.getElementById('v-country').textContent=region;
  document.getElementById('v-year').textContent=year;
  document.getElementById('v-valid').textContent=checkText;
  document.getElementById('v-status').textContent='No flags (demo) ✓';
  result.style.display='block';
}


