(function fhDotNav(){
  var dots=document.querySelectorAll('.fh-dot'); if(!dots.length) return;
  var map={};
  dots.forEach(function(d){var el=document.getElementById(d.dataset.sec); if(el) map[d.dataset.sec]=d;});
  var obs=new IntersectionObserver(function(es){
    es.forEach(function(e){
      if(e.isIntersecting){
        dots.forEach(function(d){d.classList.remove('act');});
        var d=map[e.target.id]; if(d) d.classList.add('act');
      }
    });
  },{threshold:0.35});
  Object.keys(map).forEach(function(id){var el=document.getElementById(id); if(el) obs.observe(el);});
})();

