function openMarket(key){
  var d=MARKET_DATA[key]; if(!d) return;
  document.getElementById('mo-flag').textContent=d.flag;
  document.getElementById('mo-title').textContent=d.title;
  document.getElementById('mo-subtitle').textContent=d.subtitle;
  // reuse the card's embedded photo for the overlay hero
  var card=document.querySelector('.bento-'+key);
  if(card) document.getElementById('mo-hero-img').style.backgroundImage=getComputedStyle(card).backgroundImage;
  document.getElementById('mo-stats').innerHTML=d.stats.map(function(x){
    return '<div class="mo-stat"><div class="mo-stat-n">'+x[0]+'</div><div class="mo-stat-l">'+x[1]+'</div></div>';}).join('');
  document.getElementById('mo-insight').textContent=d.insight;
  document.getElementById('mo-cars').innerHTML=d.cars.map(function(c){
    return '<div class="mo-car"><div><div class="mo-car-nm">'+c[0]+'</div><div class="mo-car-tag">'+c[1]+'</div></div><div class="mo-car-pr">'+c[2]+'</div></div>';}).join('');
  document.getElementById('mo-prices').innerHTML=d.prices.map(function(r){
    return '<div class="mo-price-row"><b>'+r[0]+'</b><span class="val">'+r[1]+'</span></div>';}).join('');
  document.getElementById('mo-tips').innerHTML=d.tips.map(function(t){
    return '<div class="mo-tip"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="m9 12 2 2 4-4"/><circle cx="12" cy="12" r="10"/></svg><span>'+t+'</span></div>';}).join('');
  var cta=document.getElementById('mo-cta-btn');
  cta.onclick=function(){ closeMarket(); openAdvisorWithPrompt('Show me cars in the '+MO_NAMES[key]+' market'); };
  var ov=document.getElementById('mkt-overlay');
  ov.classList.add('open'); ov.scrollTop=0;
  document.body.classList.add('mo-lock');
  document.addEventListener('keydown', moEsc);
}
function closeMarket(){
  document.getElementById('mkt-overlay').classList.remove('open');
  document.body.classList.remove('mo-lock');
  document.removeEventListener('keydown', moEsc);
}
function moEsc(e){ if(e.key==='Escape') closeMarket(); }

