<!-- ==================== GATE + SHOWROOM SCRIPTS ==================== -->
<script>
(function(){
  const gate = document.getElementById('introGate');
  if (!gate) return;
  const gateVid = document.getElementById('gateVid');
  const lines = document.getElementById('gateLines');
  const vignette = document.getElementById('gateVignette');
  const flash = document.getElementById('gateFlash');
  const btn = document.getElementById('exploreBtn');
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  document.documentElement.classList.add('gate-lock');

  // Pause the main hero video while the gate is up (it autoplays from page script)
  const mainHero = document.getElementById('hero-vid');
  setTimeout(() => { if (mainHero && gate && !gate.classList.contains('gone')) mainHero.pause(); }, 60);

  // Gate video: random start, cycle on end
  const srcs = Array.from({ length: 7 }, (_, i) => `./media/Hero/Hero-0${i + 1}.mp4`);
  let cur = Math.floor(Math.random() * srcs.length);
  function playGateVid(i){ gateVid.src = srcs[i]; gateVid.play().catch(()=>{}); }
  gateVid.addEventListener('ended', () => { if (accelerating) return; cur = (cur + 1) % srcs.length; playGateVid(cur); });
  gateVid.loop = false;
  playGateVid(cur);

  // Build speed-line streaks
  for (let i = 0; i < 30; i++) {
    const s = document.createElement('span');
    s.style.top = (Math.random() * 100) + '%';
    s.style.setProperty('--dur', (0.32 + Math.random() * 0.4).toFixed(2) + 's');
    s.style.setProperty('--del', (Math.random() * 0.5).toFixed(2) + 's');
    s.style.opacity = (0.35 + Math.random() * 0.65).toFixed(2);
    s.style.height = (1 + Math.random() * 2.4).toFixed(1) + 'px';
    lines.appendChild(s);
  }

  let accelerating = false;
  function explore(){
    if (accelerating) return;
    accelerating = true;

    const finish = () => {
      gate.classList.add('leave');
      document.documentElement.classList.remove('gate-lock');
      window.scrollTo(0, 0);
      document.body.classList.add('arrive');
      if (mainHero) mainHero.play().catch(()=>{});
      // Kick the hero reveal animations now that the page is visible
      document.querySelectorAll('.hero [data-r]').forEach((el, i) => {
        setTimeout(() => el.classList.add('vis'), 120 + i * 110);
      });
      setTimeout(() => { gate.classList.add('gone'); gateVid.pause(); gateVid.removeAttribute('src'); gateVid.load(); }, 550);
      setTimeout(() => document.body.classList.remove('arrive'), 1000);
    };

    if (reduced) { finish(); return; }

    // Phase 1 — throttle down: hide copy, ramp video speed, zoom in
    gate.classList.add('accel');
    try { gateVid.playbackRate = 2.5; } catch(e){}
    setTimeout(() => { lines.classList.add('on'); vignette.classList.add('on'); }, 140);

    // Phase 2 — flash at peak speed
    setTimeout(() => {
      flash.animate(
        [{ opacity: 0 }, { opacity: 0.95, offset: 0.45 }, { opacity: 0 }],
        { duration: 480, easing: 'ease-out' }
      );
    }, 820);

    // Phase 3 — leave the gate, settle into the page
    setTimeout(finish, 1020);
  }

  btn.addEventListener('click', explore);
  // Scroll intent also launches
  gate.addEventListener('wheel', (e) => { if (e.deltaY > 12) explore(); }, { passive: true });
  let touchY = null;
  gate.addEventListener('touchstart', (e) => { touchY = e.touches[0].clientY; }, { passive: true });
  gate.addEventListener('touchmove', (e) => {
    if (touchY !== null && touchY - e.touches[0].clientY > 36) { explore(); touchY = null; }
  }, { passive: true });
  window.addEventListener('keydown', (e) => {
    if (!gate.classList.contains('gone') && (e.key === 'Enter' || e.key === ' ') && document.activeElement !== btn) explore();
  });
  btn.focus({ preventScroll: true });
})();
</script>

